import { createHash } from "node:crypto";

import {
  caddyToken,
  type CaddyDirective,
  type CaddyfileDocument,
  type CaddySiteBlock,
  renderCaddyfile,
} from "./caddyfile";
import {
  type SiteConfig,
  type SiteConfigInput,
  validateSiteConfig,
} from "./contracts";

/** Fixed header, so a manual edit of the generated file is recognizable as such. */
export const SITES_CADDY_HEADER = [
  "Generated by Caddy Visualizer. Do not edit: changes will be overwritten.",
] as const;

export interface GeneratedSitesCaddy {
  /** Content of `sites.caddy`, ends with a newline. */
  content: string;
  /** SHA-256 (hex) of `content`, e.g. for drift detection. */
  sha256: string;
  /** Hostnames of the sites contained, in output order. */
  hostnames: string[];
}

export class SiteGeneratorError extends Error {
  override name = "SiteGeneratorError";
}

/** The site data the generator needs; matches the stored site model. */
export type GeneratorSite = SiteConfigInput;

/**
 * Pure and deterministic: the same sites always produce byte-identical output,
 * independent of input order, IDs, timestamps or locale.
 *
 * Pipeline: sites → validated model (`validateSiteInput`, also for data read
 * from the database) → Caddyfile model (`CaddyfileDocument`) → text.
 */
export interface GeneratorOptions {
  /**
   * Adds `import access_log` to every site; only when the main Caddyfile
   * defines that snippet (an import of a missing snippet fails).
   */
  accessLog?: boolean;
}

export function generateSitesCaddy(
  sites: readonly GeneratorSite[],
  options: GeneratorOptions = {},
): GeneratedSitesCaddy {
  const included = enabledSorted(sites);
  const content = renderCaddyfile(documentFor(included, options));
  return {
    content,
    sha256: createHash("sha256").update(content).digest("hex"),
    hostnames: included.map((site) => site.hostname),
  };
}

/** The intermediate Caddyfile model, e.g. for later extensions or inspection. */
export function buildSitesDocument(
  sites: readonly GeneratorSite[],
  options: GeneratorOptions = {},
): CaddyfileDocument {
  return documentFor(enabledSorted(sites), options);
}

function documentFor(
  sites: readonly SiteConfig[],
  options: GeneratorOptions,
): CaddyfileDocument {
  return {
    header: SITES_CADDY_HEADER,
    sites: sites.map((site) => siteBlock(site, options)),
  };
}

function enabledSorted(sites: readonly GeneratorSite[]): SiteConfig[] {
  const valid = sites.filter((site) => site.enabled).map(validated);

  const seen = new Set<string>();
  for (const { hostname } of valid) {
    if (seen.has(hostname)) {
      throw new SiteGeneratorError(`Duplicate site hostname: ${hostname}`);
    }
    seen.add(hostname);
  }
  // Code unit order, not localeCompare: must not depend on the runtime locale.
  return valid.sort((a, b) =>
    a.hostname < b.hostname ? -1 : a.hostname > b.hostname ? 1 : 0,
  );
}

function validated(site: GeneratorSite): SiteConfig {
  const result = validateSiteConfig(site);
  if (!result.ok) {
    // Field names only: the values are untrusted, long or secret (hashes).
    throw new SiteGeneratorError(
      `Invalid site data in fields: ${result.fields.join(", ")}`,
    );
  }
  return result.value;
}

function siteBlock(
  site: SiteConfig,
  { accessLog = false }: GeneratorOptions,
): CaddySiteBlock {
  return {
    addresses: [siteAddress(site)],
    directives: [
      ...(accessLog
        ? [{ name: caddyToken("import"), args: [caddyToken("access_log")] }]
        : []),
      ...basicAuth(site),
      site.kind === "redirect" ? redirect(site) : reverseProxy(site),
    ],
  };
}

/** `tls: off` uses an `http://` address: Caddy then serves plain HTTP only. */
function siteAddress(site: SiteConfig) {
  return caddyToken(
    site.tls === "off" ? `http://${site.hostname}` : site.hostname,
  );
}

/**
 * `basic_auth` (Caddy ≥ 2.8; 2.7 only knows `basicauth`) with bcrypt, Caddy's
 * default algorithm. Caddy orders it before `reverse_proxy` and after its
 * HTTP→HTTPS redirect, so credentials are only ever sent over HTTPS.
 */
function basicAuth(site: SiteConfig): CaddyDirective[] {
  if (site.basicAuthUsername === null || site.basicAuthHash === null) return [];
  return [
    {
      name: caddyToken("basic_auth"),
      args: [],
      block: [
        {
          name: caddyToken(site.basicAuthUsername),
          args: [caddyToken(site.basicAuthHash)],
        },
      ],
    },
  ];
}

/**
 * An `https://` upstream already makes Caddy use TLS; skipping the check only
 * needs `tls_insecure_skip_verify` in the HTTP transport.
 */
function reverseProxy(site: SiteConfig): CaddyDirective {
  return {
    name: caddyToken("reverse_proxy"),
    args: [caddyToken(site.upstream ?? "")],
    ...(site.upstreamSkipTlsVerify
      ? {
          block: [
            {
              name: caddyToken("transport"),
              args: [caddyToken("http")],
              block: [
                { name: caddyToken("tls_insecure_skip_verify"), args: [] },
              ],
            },
          ],
        }
      : {}),
  };
}

/** `redir <to> <code>`; with an explicit code the target is never read as a matcher. */
function redirect(site: SiteConfig): CaddyDirective {
  return {
    name: caddyToken("redir"),
    args: [
      caddyToken(site.redirectTarget ?? ""),
      caddyToken(String(site.redirectCode)),
    ],
  };
}
